create or replace function public.get_missing_stock_costs(p_boutique_id text)
returns table(entry_id bigint,product_id bigint,product_name text,qty numeric,entry_date timestamptz,supplier_name text,reference text)
language plpgsql stable security definer set search_path='pg_catalog','public','private' as $$ begin if auth.uid() is null or not (private.auth_is_super_admin() or exists(select 1 from public.boutique_assignments a where a.boutique_id=p_boutique_id and a.user_id=auth.uid() and a.role='owner')) then raise exception 'forbidden'; end if; return query select se.id,se.product_id,p.nom,se.qty,se.entry_date,coalesce(s.nom,se.note),se.reference from public.stock_entries se join public.products p on p.boutique_id=se.boutique_id and p.id=se.product_id left join public.suppliers s on s.boutique_id=se.boutique_id and s.id=se.supplier_id where se.boutique_id=p_boutique_id and se.qty>0 and se.type='achat' and coalesce(se.prix_unit,0)<=0 order by se.entry_date,se.id; end $$;
revoke all on function public.get_missing_stock_costs(text) from public,anon; grant execute on function public.get_missing_stock_costs(text) to authenticated;
create or replace function public.set_stock_entry_reference_cost(p_boutique_id text,p_entry_id bigint,p_unit_cost numeric) returns void language plpgsql security definer set search_path='pg_catalog','public','private' as $$ declare v_entry public.stock_entries%rowtype; v_product text; begin if auth.uid() is null or not (private.auth_is_super_admin() or exists(select 1 from public.boutique_assignments a where a.boutique_id=p_boutique_id and a.user_id=auth.uid() and a.role='owner')) then raise exception 'forbidden'; end if; if p_unit_cost is null or p_unit_cost<=0 then raise exception 'invalid unit cost'; end if; select * into v_entry from public.stock_entries where boutique_id=p_boutique_id and id=p_entry_id for update; if not found or v_entry.qty<=0 or v_entry.type<>'achat' then raise exception 'eligible stock entry not found'; end if; if coalesce(v_entry.prix_unit,0)>0 then raise exception 'cost already defined'; end if; update public.stock_entries set prix_unit=round(p_unit_cost,4) where id=p_entry_id; select nom into v_product from public.products where boutique_id=p_boutique_id and id=v_entry.product_id; insert into public.audit_log(boutique_id,user_id,action,detail,icon,created_at,source) values(p_boutique_id,auth.uid(),'Prix d''achat historique complété',coalesce(v_product,'Produit')||' · réception #'||p_entry_id||' · '||round(p_unit_cost,4)||' F/unité','🧾',now(),'native'); end $$;
revoke all on function public.set_stock_entry_reference_cost(text,bigint,numeric) from public,anon; grant execute on function public.set_stock_entry_reference_cost(text,bigint,numeric) to authenticated;